"source" | 
/**
 * The pre-existing Tauri updater-plugin flow, untouched.
 */
"plugin"
export type SourceUpdateState = "up_to_date" | "available" | 
/**
 * The build cannot be related to `main` (history rewritten, commit not on
 * GitHub, diverged). Never installable, never prompts automatically.
 */
"untracked"
/**
 * Command failures. Serialized as enum tags only.
 */
export type SpeakerCmdError = 
/**
 * The Speaker model is not installed, so no enrollment can start.
 */
"ModelMissing" | { Enroll: EnrollError } | 
/**
 * The voiceprint store failed, or the runtime is not available.
 */
"StoreFailed"
/**
 * How strict the optional speaker filter is (design A8). Thresholds live with
 * the speaker model constants, not here.
 */
export type SpeakerSensitivity = "lenient" | "balanced" | "strict"
/**
 * Numbers and booleans only.
 */
export type SpeakerStatus = { enrolled: boolean; enrollment_active: boolean; model_ready: boolean }
/**
 * Result of one counted step. Numbers and booleans only.
 */
export type StepResult = { speech_ms: number; ok: boolean }
/**
 * Phase of the streaming overlay card, emitted to drive its UI state.
 */
export type StreamPhase = 
/**
 * Receiving audio / live text (or waiting for the stream to begin). Rust
 * does not emit this today; the frontend starts in this phase and Rust only
 * emits transitions away from it.
 */
"listening" | 
/**
 * Finalizing or post-processing — show a spinner.
 */
"working"
/**
 * Emitted to switch the streaming overlay to a working spinner.
 */
export type StreamPhaseEvent = { phase: StreamPhase; 
/**
 * Present only when `phase` is `Working`.
 */
kind?: StreamWorkKind | null }
/**
 * Live transcription snapshot emitted to the overlay during a streaming run.
 * `committed` is the append-only, flicker-free prefix; `tentative` is the
 * volatile suffix the model may still rewrite.
 */
export type StreamTextEvent = { committed: string; tentative: string }
/**
 * Semantic kind of "working" phase, used to localize the spinner label.
 */
export type StreamWorkKind = "transcribing" | "polishing"
/**
 * UI appearance mode. `System` follows the OS `prefers-color-scheme`; `Light`
 * and `Dark` force one of the two palettes Vox already ships. `Aurora` is a
 * third, non-adaptive accent palette (teal/violet on deep slate) a user can
 * opt into explicitly -- it never changes what `System`/`Light`/`Dark` look
 * like and is not anyone's default.
 */
export type Theme = "system" | "light" | "dark" | "aurora" | 
/**
 * User-edited palette, see `CustomThemeColors`.
 */
"custom"
export type TranscribeAcceleratorSetting = "auto" | "cpu" | "gpu"
export type TtsComposerFallback = 
/**
 * Speak a fixed short sentence when composition fails.
 */
"short_notice" | 
/**
 * Speak the (capped) reply verbatim when composition fails.
 */
"verbatim" | 
/**
 * Say nothing when composition fails.
 */
"silent"
export type TtsComposerMode = 
/**
 * Legacy behavior: speak the reply text as-is.
 */
"off" | 
/**
 * Ask an OpenAI-compatible provider already configured in settings.
 */
"model" | 
/**
 * Run a user-configured local command.
 */
"command"
export type TtsComposerSettings = { mode: TtsComposerMode; provider_id: string; model: string; command_path: string; command_args: string; prompt_flag: string; command_ack: string; timeout_secs: number; style: string; send_user_utterance: boolean; fallback: TtsComposerFallback }
/**
 * Partial update. `None` = untouched. For strings `Some("")` CLEARS (for
 * `prompt_flag` it resets to the default `-p`; for `provider_id` an empty
 * string is invalid).
 */
export type TtsComposerSettingsPatch = { mode: TtsComposerMode | null; provider_id: string | null; model: string | null; command_path: string | null; command_args: string | null; prompt_flag: string | null; timeout_secs: number | null; style: string | null; send_user_utterance: boolean | null; fallback: TtsComposerFallback | null; 
/**
 * Honored ONLY when the same patch also supplies command_path,
 * command_args and prompt_flag.
 */
acknowledge_command: boolean | null }
/**
 * Which engine speaks spoken replies.
 */
export type TtsEngine = 
/**
 * The local Phonon voice: a pure-Rust English model (needs a one-time download, macOS only).
 */
"phonon" | 
/**
 * The local neural voice (needs a one-time model download).
 */
"natural" | 
/**
 * The operating system voice (default). Also what any unrecognised stored value means, so a
 * bad settings file can never stop the app from loading.
 */
"system"
/**
 * One row of the engine picker.
 */
export type TtsEngineInfo = { id: TtsEngine; recommended: boolean; runtime: TtsRuntime; requires_download: boolean; size_bytes: number; english_only: boolean; supports_voice_choice: boolean; supports_rate: boolean; supported_on_platform: boolean; license: string }
/**
 * What runs the engine's speech synthesis.
 */
export type TtsRuntime = 
/**
 * Pure Rust, no separate native runtime.
 */
"pure_rust" | 
/**
 * Runs on ONNX Runtime.
 */
"onnx_runtime" | 
/**
 * Provided by the operating system.
 */
"operating_system"
/**
 * One installed speech voice, as reported by `say -v '?'`.
 */
export type TtsVoice = { 
/**
 * Voice name exactly as `say -v` accepts it (passes `sanitize_voice`).
 */
name: string; 
/**
 * Locale code such as `en_US` or `es_419`.
 */
locale: string }
export type TypingTool = "auto" | "wtype" | "kwtype" | "dotool" | "ydotool" | "xdotool"
export type VadBackend = "silero" | "earshot"
/**
 * One preview hit (DESIGN Rev 5, 3.6). Plain text fields only.
 */
export type VaultHitDto = { rel: string; heading: string; snippet: string; note_date: string | null }
/**
 * Status DTO for the settings UI (DESIGN Rev 5, 3.6). `tool_support` is a plain string here.
 */
export type VaultIndexStatusDto = { notes: number; chunks: number; skipped: number; last_refresh_ms: number | null; refreshing: boolean; last_error_kind: string | null; 
/**
 * untested | supported | unsupported | unknown, for the current route key.
 */
tool_support: string }
export type VoiceShortcut = { phrase: string; action: VoiceShortcutAction }
export type VoiceShortcutAction = { type: "open_url"; url: string } | { type: "open_path"; path: string } | { type: "open_app"; name: string }
/**
 * What a wake-word detection does while no conversation session is running.
 */
export type WakeWordAction = 
/**
 * Start a turn-based conversation session.
 */
"conversation" | 
/**
 * One-shot voice request (today's behaviour, default). Also what any unrecognised stored
 * value means, so a bad settings file can never stop the app from loading.
 */
"voice_request"
/**
 * A wake-word detection emitted by an engine. Must be Serialize/Type so it
 * can be sent as a Tauri event payload (see `commands/wakeword.rs`'s
 * `wakeword://detected` event, task W6) and exported to the TypeScript
 * bindings via specta.
 */
export type WakeWordDetection = { model_name: string; confidence: number; timestamp_ms: number }
export type WindowsMicrophonePermissionStatus = { supported: boolean; overall_access: PermissionAccess; device_access: PermissionAccess; app_access: PermissionAccess; desktop_app_access: PermissionAccess }

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
